contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(msg.sender != address(0), "invalid sender");

        // Snapshot before-values through the public getters.
        uint64 beforeNumber = c.number();
        uint64 beforeTimestamp = c.timestamp();
        uint256 beforeBasefee = c.basefee();
        bytes32 beforeHash = c.hash();
        uint64 beforeSequenceNumber = c.sequenceNumber();
        bytes32 beforeBatcherHash = c.batcherHash();
        uint256 beforeL1FeeOverhead = c.l1FeeOverhead();
        uint256 beforeL1FeeScalar = c.l1FeeScalar();

        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The depositor account is the only allowed caller. Since this test contract
        // is the caller and cannot be the depositor account, the call must revert and
        // no L1 block value may change.
        require(reverted, "setL1BlockValues call from non-depositor unexpectedly succeeded");

        assert(
            c.number() == beforeNumber &&
            c.timestamp() == beforeTimestamp &&
            c.basefee() == beforeBasefee &&
            c.hash() == beforeHash &&
            c.sequenceNumber() == beforeSequenceNumber &&
            c.batcherHash() == beforeBatcherHash &&
            c.l1FeeOverhead() == beforeL1FeeOverhead &&
            c.l1FeeScalar() == beforeL1FeeScalar
        );
    }

    receive() external payable {}
}

